mapper.update:
UPDATE tool_invocation
SET status = #{status},
	response_payload = #{responsePayload,typeHandler=com.yourcompany.salesagent.shared.persistence.JsonbMapTypeHandler},
	external_operation_id = #{externalOperationId},
	retryable = #{retryable},
	error_code = #{errorCode},
	error_message = #{errorMessage},
	latency_ms = #{latencyMs},
	completed_at = #{now}
WHERE organization_id = #{organizationId}
  AND action_request_id = #{actionRequestId}
  AND attempt_no = #{attemptNo}
